ALTER TABLE "cost_entries" DROP CONSTRAINT "cost_entries_source_check";--> statement-breakpoint
ALTER TABLE "cost_entries" DROP CONSTRAINT "cost_entries_idempotency_check";--> statement-breakpoint
ALTER TABLE "cost_entries" ADD COLUMN "background_job_id" uuid;--> statement-breakpoint
CREATE UNIQUE INDEX "cost_entries_job_call_idx" ON "cost_entries" USING btree ("background_job_id","call_index");--> statement-breakpoint
ALTER TABLE "cost_entries" ADD CONSTRAINT "cost_entries_source_check" CHECK (("cost_entries"."run_id" is not null)::integer + ("cost_entries"."capture_id" is not null)::integer + ("cost_entries"."background_job_id" is not null)::integer = 1);--> statement-breakpoint
ALTER TABLE "cost_entries" ADD CONSTRAINT "cost_entries_idempotency_check" CHECK (("cost_entries"."run_id" is not null and "cost_entries"."idempotency_key" = 'cost:' || "cost_entries"."run_id"::text || ':' || "cost_entries"."call_index"::text) or ("cost_entries"."capture_id" is not null and ("cost_entries"."idempotency_key" = 'teach:' || "cost_entries"."capture_id"::text || ':asr:' || ("cost_entries"."call_index" - 1)::text or "cost_entries"."idempotency_key" = 'teach:' || "cost_entries"."capture_id"::text || ':skill:' || "cost_entries"."call_index"::text)) or ("cost_entries"."background_job_id" is not null and "cost_entries"."idempotency_key" = 'cost:job:' || "cost_entries"."background_job_id"::text || ':' || "cost_entries"."call_index"::text));
